            .expect("a tool_execution entry");
        assert_eq!(exec.arguments, serde_json::json!({ "text": "hello" }));
        assert_eq!(exec.result, "hello");

        mgr.close("stream-fix").expect("close");
        std::fs::remove_dir_all(&dir).unwrap_or(());
    }

