//! # hanihi-session-analyser
//!
//! Library and CLI for analysing hānihi session event logs.
//!
//! Reads a session's `events.jsonl` directly (no model connection, no
//! session lock) and folds it into per-turn and aggregate metrics:
//! completed turns, tool-call counts, token usage, model latency, and
//! errors.

pub mod error;
pub mod metrics;
pub mod read;

pub use error::AnalyseError;
pub use metrics::{LatencyStats, SessionMetrics, TurnMetrics, analyse};
pub use read::{parse_log, read_log};

//! Error type for the session analyser.
//!
//! Hand-written `Display`/`Error` impls, per workspace conventions (no
//! `thiserror`/`anyhow`).

use std::fmt;

/// Errors produced while reading or analysing a session event log.
#[derive(Debug)]
pub enum AnalyseError {
    /// The log file could not be read.
    Io(std::io::Error),
    /// A line in the log was not valid JSON.
    Json {
        /// 1-based line number in the log file.
        line: usize,
        /// Underlying JSON error.
        source: serde_json::Error,
    },
}

impl fmt::Display for AnalyseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AnalyseError::Io(e) => write!(f, "io error: {e}"),
            AnalyseError::Json { line, source } => {
                write!(f, "json error at line {line}: {source}")
            }
        }
    }
}

impl std::error::Error for AnalyseError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            AnalyseError::Io(e) => Some(e),
            AnalyseError::Json { source, .. } => Some(source),
        }
    }
}

impl From<std::io::Error> for AnalyseError {
    fn from(e: std::io::Error) -> Self {
        AnalyseError::Io(e)
    }
}

//! Reading and parsing session event logs.

use std::fs;
use std::path::Path;

use hanihi_core::session::log::LogEntry;

use crate::error::AnalyseError;

/// Parse every entry from an `events.jsonl` string.
///
/// Blank lines are skipped; every other line must be one complete JSON
/// [`LogEntry`]. Line numbers in errors are 1-based.
pub fn parse_log(contents: &str) -> Result<Vec<LogEntry>, AnalyseError> {
    let mut entries = Vec::new();
    for (index, line) in contents.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let entry = serde_json::from_str(line).map_err(|source| AnalyseError::Json {
            line: index + 1,
            source,
        })?;
        entries.push(entry);
    }
    Ok(entries)
}

/// Read and parse a session's `events.jsonl` file.
pub fn read_log(path: &Path) -> Result<Vec<LogEntry>, AnalyseError> {
    let contents = fs::read_to_string(path)?;
    parse_log(&contents)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn parses_valid_lines_and_skips_blanks() {
        let log = format!(
            "{}\n\n{}\n",
            json!({"kind":"user_input","ts":"2026-01-01T00:00:00Z","turn":1,"data":{"text":"hi"}}),
            json!({"kind":"turn_complete","ts":"2026-01-01T00:00:01Z","turn":1,"data":{"text":"hi","tool_calls":0}}),
        );
        let entries = parse_log(&log).expect("parse succeeds");
        assert_eq!(entries.len(), 2);
        assert!(matches!(entries[0], LogEntry::UserInput { .. }));
        assert!(matches!(entries[1], LogEntry::TurnComplete { .. }));
    }

    #[test]
    fn reports_line_number_for_bad_json() {
        let log = format!(
            "{}\nnot json\n",
            json!({"kind":"user_input","ts":"2026-01-01T00:00:00Z","turn":1,"data":{"text":"hi"}}),
        );
        let err = parse_log(&log).expect_err("bad line must fail");
        match err {
            AnalyseError::Json { line, .. } => assert_eq!(line, 2),
            other => panic!("expected Json error, got {other:?}"),
        }
    }

    #[test]
    fn reads_from_disk() {
        let path = std::env::temp_dir().join(format!(
            "hanihi-analyser-read-{}.jsonl",
            uuid::Uuid::new_v4()
        ));
        let log = json!({"kind":"turn_complete","ts":"2026-01-01T00:00:00Z","turn":1,"data":{"text":"x","tool_calls":0}});
        std::fs::write(&path, format!("{log}\n")).expect("write log");
        let entries = read_log(&path).expect("read succeeds");
        assert_eq!(entries.len(), 1);
        std::fs::remove_file(&path).unwrap_or(());
    }
}

//! Folding a session event log into metrics.

use hanihi_core::session::log::LogEntry;

/// Metrics for a single completed turn.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct TurnMetrics {
    /// 1-based turn number.
    pub turn: u64,
    /// Final answer text of the turn.
    pub text: String,
    /// Tool executions in the turn.
    pub tool_calls: usize,
    /// Model input tokens for the turn.
    pub tokens_in: u64,
    /// Model output tokens for the turn.
    pub tokens_out: u64,
    /// Number of model calls (llm_prompt/llm_response pairs) in the turn.
    pub model_calls: usize,
    /// Errors recorded in the turn.
    pub errors: usize,
}

/// Latency statistics over model calls in milliseconds.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct LatencyStats {
    /// Number of measured model calls.
    pub calls: usize,
    /// Total latency across measured calls.
    pub total_ms: i64,
    /// Minimum observed latency.
    pub min_ms: i64,
    /// Maximum observed latency.
    pub max_ms: i64,
}

/// Aggregate metrics for a session log.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct SessionMetrics {
    /// Per-turn metrics in turn order.
    pub turns: Vec<TurnMetrics>,
    /// Cumulative model input tokens.
    pub tokens_in: u64,
    /// Cumulative model output tokens.
    pub tokens_out: u64,
    /// Total tool executions.
    pub tool_calls: usize,
    /// Total errors recorded.
    pub errors: usize,
    /// Latency statistics across all model calls.
    pub latency: LatencyStats,
}

/// Analyse a parsed session log.
///
/// Only completed turns (closed by `turn_complete`) produce a
/// [`TurnMetrics`] row. Model usage and errors are attributed to the most
/// recently completed turn; entries after the last completed turn are
/// counted only in the session totals.
pub fn analyse(entries: &[LogEntry]) -> SessionMetrics {
    let mut metrics = SessionMetrics::default();
    // Pending model-call latency for the current turn: the ts of the last
    // llm_prompt not yet matched by an llm_response.
    let mut pending_prompt_ts: Option<chrono::DateTime<chrono::Utc>> = None;

    for entry in entries {
        match entry {
            LogEntry::LlmPrompt { ts, .. } => {
                pending_prompt_ts = Some(*ts);
            }
            LogEntry::LlmResponse { ts, data, .. } => {
                if let Some(prompt_ts) = pending_prompt_ts.take() {
                    let ms = (*ts - prompt_ts).num_milliseconds();
                    if ms >= 0 {
                        let latency = &mut metrics.latency;
                        latency.calls += 1;
                        latency.total_ms += ms;
                        latency.min_ms = if latency.calls == 1 {
                            ms
                        } else {
                            latency.min_ms.min(ms)
                        };
                        latency.max_ms = latency.max_ms.max(ms);
                    }
                }
                let (tin, tout) = (
                    u64::from(data.usage.input_tokens),
                    u64::from(data.usage.output_tokens),
                );
                metrics.tokens_in += tin;
                metrics.tokens_out += tout;
                let turn = metrics.turns.last_mut().map(|t| &mut *t);
                if let Some(t) = turn {
                    t.tokens_in += tin;
                    t.tokens_out += tout;
                    t.model_calls += 1;
                }
            }
            LogEntry::ToolExecution { .. } => {
                metrics.tool_calls += 1;
                if let Some(t) = metrics.turns.last_mut() {
                    t.tool_calls += 1;
                }
            }
            LogEntry::TurnComplete { turn, data, .. } => {
                metrics.turns.push(TurnMetrics {
                    turn: *turn,
                    text: data.text.clone(),
                    tool_calls: data.tool_calls,
                    ..TurnMetrics::default()
                });
            }
            LogEntry::Error { .. } => {
                metrics.errors += 1;
                if let Some(t) = metrics.turns.last_mut() {
                    t.errors += 1;
                }
            }
            // Lifecycle and user-input entries carry no metric data.
            LogEntry::SessionCreated { .. }
            | LogEntry::SessionOpened { .. }
            | LogEntry::SessionClosed { .. }
            | LogEntry::UserInput { .. } => {}
        }
    }

    metrics
}

#[cfg(test)]
mod tests {
    use super::*;
    use hanihi_core::session::log::{ToolCallData, UsageData};
    use serde_json::json;

    fn ts(secs: i64) -> chrono::DateTime<chrono::Utc> {
        chrono::DateTime::from_timestamp(secs, 0)
            .expect("valid timestamp")
            .to_utc()
    }

    #[test]
    fn empty_log_yields_defaults() {
        let metrics = analyse(&[]);
        assert_eq!(metrics, SessionMetrics::default());
    }

    #[test]
    fn folds_complete_turn_usage_tools_and_latency() {
        let entries = vec![
            LogEntry::user_input(ts(0), 1, "hi".into()),
            LogEntry::llm_prompt(ts(1), 1, "d".into(), "m".into(), json!([]), json!([])),
            LogEntry::llm_response(
                ts(3),
                1,
                Some("m1".into()),
                None,
                None,
                Some(vec![ToolCallData {
                    id: "c1".into(),
                    name: "echo".into(),
                    arguments: json!({"text": "hi"}),
                }]),
                UsageData {
                    input_tokens: 10,
                    output_tokens: 4,
                },
            ),
            LogEntry::tool_execution(
                ts(4),
                1,
                "c1".into(),
                "c1".into(),
                "echo".into(),
                json!({"text": "hi"}),
                "hi".into(),
            ),
            LogEntry::llm_prompt(ts(5), 1, "d".into(), "m".into(), json!([]), json!([])),
            LogEntry::llm_response(
                ts(7),
                1,
                Some("m2".into()),
                Some("hi".into()),
                None,
                None,
                UsageData {
                    input_tokens: 12,
                    output_tokens: 3,
                },
            ),
            LogEntry::turn_complete(ts(8), 1, "hi".into(), 1),
        ];

        let metrics = analyse(&entries);

        assert_eq!(metrics.turns.len(), 1);
        let turn = &metrics.turns[0];
        assert_eq!(turn.turn, 1);
        assert_eq!(turn.text, "hi");
        assert_eq!(turn.tool_calls, 1);
        assert_eq!(turn.tokens_in, 22);
        assert_eq!(turn.tokens_out, 7);
        assert_eq!(turn.model_calls, 2);
        assert_eq!(turn.errors, 0);

        assert_eq!(metrics.tokens_in, 22);
        assert_eq!(metrics.tokens_out, 7);
        assert_eq!(metrics.tool_calls, 1);
        assert_eq!(metrics.errors, 0);

        assert_eq!(metrics.latency.calls, 2);
        assert_eq!(metrics.latency.total_ms, 4000);
        assert_eq!(metrics.latency.min_ms, 2000);
        assert_eq!(metrics.latency.max_ms, 2000);
    }

    #[test]
    fn errors_attach_to_last_completed_turn() {
        let entries = vec![
            LogEntry::user_input(ts(0), 1, "bad".into()),
            LogEntry::turn_complete(ts(1), 1, "oops".into(), 0),
            LogEntry::error(ts(2), 1, hanihi_core::session::log::ErrorStage::ToolExecution, "boom".into()),
            LogEntry::user_input(ts(3), 2, "next".into()),
        ];

        let metrics = analyse(&entries);

        assert_eq!(metrics.errors, 1);
        assert_eq!(metrics.turns[0].errors, 1);
        assert_eq!(metrics.turns.len(), 1);
    }

    #[test]
    fn ignores_negative_latency() {
        // Response ts before prompt ts must not corrupt stats.
        let entries = vec![
            LogEntry::llm_prompt(ts(5), 1, "d".into(), "m".into(), json!([]), json!([])),
            LogEntry::llm_response(
                ts(2),
                1,
                Some("m1".into()),
                Some("x".into()),
                None,
                None,
                UsageData {
                    input_tokens: 1,
                    output_tokens: 1,
                },
            ),
            LogEntry::turn_complete(ts(6), 1, "x".into(), 0),
        ];

        let metrics = analyse(&entries);
        assert_eq!(metrics.latency.calls, 0);
        assert_eq!(metrics.tokens_in, 1);
    }
}

//! # hanihi-session-analyser
//!
//! CLI for [`hanihi_session_analyser`]: reads a session's `events.jsonl`
//! directly (no model connection, no session lock) and prints per-turn
//! and aggregate metrics.

use std::path::PathBuf;

use hanihi_session_analyser::{analyse, read_log};

fn main() {
    // Positional: working dir (default ./working), then session name
    // (default default-session). Simple CLI, no clap dependency.
    let args: Vec<String> = std::env::args().skip(1).collect();
    let (working_dir, session_name) = match args.as_slice() {
        [] => (PathBuf::from("./working"), "default-session".to_string()),
        [name] => (PathBuf::from("./working"), name.clone()),
        [dir, name] => (PathBuf::from(dir), name.clone()),
        _ => {
            eprintln!("usage: hanihi-session-analyser [WORKING_DIR] [SESSION_NAME]");
            std::process::exit(2);
        }
    };

    let log_path = working_dir.join("sessions").join(&session_name).join("events.jsonl");

    let entries = match read_log(&log_path) {
        Ok(entries) => entries,
        Err(e) => {
            eprintln!("error reading {}: {e}", log_path.display());
            std::process::exit(1);
        }
    };

    let metrics = analyse(&entries);

    if metrics.turns.is_empty() {
        println!("session '{session_name}': no completed turns");
        return;
    }

    for turn in &metrics.turns {
        println!(
            "[turn {} | tool calls: {} | tokens: {} in / {} out | model calls: {}]",
            turn.turn, turn.tool_calls, turn.tokens_in, turn.tokens_out, turn.model_calls
        );
    }

    println!(
        "turns: {} | cumulative tokens: {} in / {} out | tool calls: {} | errors: {}",
        metrics.turns.len(),
        metrics.tokens_in,
        metrics.tokens_out,
        metrics.tool_calls,
        metrics.errors
    );

    if metrics.latency.calls > 0 {
        println!(
            "latency: {} model call(s), avg {}ms, min {}ms, max {}ms",
            metrics.latency.calls,
            metrics.latency.total_ms / metrics.latency.calls as i64,
            metrics.latency.min_ms,
            metrics.latency.max_ms
        );
    }
}
